'use strict';
let bloomNow = Date.now(), storageIssue = false, previewFixture = false;
function loadBloom() { const g = saved?.garden; return g?.version === 1 ? Bloom.tick(g, bloomNow) : Bloom.create(crypto.randomUUID(), Math.random(), bloomNow); }
let garden = loadBloom();
window.getGarden = () => garden; window.isBloomFixture = () => previewFixture; window.focusIsRunning = () => garden.phase === 'focus'; window.bloomClock = () => timerText();
function persistBloom() { if (previewFixture || demoFixture) return; for (const flower of garden.collection) { if (!R.flowers.includes(flower.id)) reward('flower', flower.id, null); } storageIssue = !saveAll(); }
function artIndex(s = garden) { return s.plant.focusMs >= Bloom.TARGET ? 5 + Bloom.species.indexOf(s.plant.species) : s.plant.focusMs >= 75 * Bloom.MIN ? 4 : s.plant.focusMs >= 50 * Bloom.MIN ? 3 : s.plant.focusMs >= 25 * Bloom.MIN ? 2 : s.plant.focusMs >= 10 * Bloom.MIN ? 1 : 0 }
function flowerArt(index, cls = '') { return `<span class="flower-sprite ${cls}" role="img" aria-label="${index < 5 ? ['Planted seed', 'Little sprout', 'New leaves', 'Growing stem', 'Flower bud'][index] : Bloom.species[index - 5]}" style="--flower-x:${index % 5 * 25}%;--flower-y:${index < 5 ? 0 : 100}%"></span>` }
function timerText() { let remaining = garden.phase === 'pausedFocus' && garden.remainingMs === 0 ? Bloom.BLOCK - garden.plant.focusMs % Bloom.BLOCK : garden.remainingMs; let sec = Math.ceil(remaining / 1000); return `${Math.floor(sec / 60).toString().padStart(2, '0')}:${(sec % 60).toString().padStart(2, '0')}` }
function bloomControls() { if (garden.phase === 'bloomed') return `<button class="primary" data-bloom="next">Plant another seed</button><button data-bloom="garden">View Garden</button>`; if (['focus', 'break'].includes(garden.phase)) return '<button class="primary" data-bloom="pause">Pause</button><button data-bloom="save">Save for later</button>'; if (garden.phase === 'pausedBreak') return '<button class="primary" data-bloom="resume">Resume break</button>'; return `<button class="primary" data-bloom="${garden.phase === 'pausedFocus' ? 'resume' : 'start'}">${garden.phase === 'pausedFocus' ? 'Continue growing' : 'Start 25 minutes'}</button><button data-bloom="short">Focus 10 min</button>`; }
function bloomCard(compact = false) { let m = garden.plant.focusMs / Bloom.MIN, stage = Bloom.stage(garden), br = garden.phase.toLowerCase().includes('break'), done = garden.phase === 'bloomed'; return `<section class="bloom-card ${compact ? 'bloom-small' : ''}" data-bloom-card="${compact ? 'compact' : 'full'}"><div class="bloom-label"><span class="eyebrow">${done ? 'A flower, all yours' : br ? 'A little rest' : garden.phase === 'pausedFocus' ? 'Growth saved' : 'Growing together'}</span><span class="small">${Math.min(4, Math.floor(m / 25))} / 4 blocks</span></div><div class="bloom-visual">${flowerArt(artIndex())}<div class="bloom-time"><strong data-bloom-clock>${done ? 'Bloomed!' : timerText()}</strong><span>${done ? esc(garden.plant.species) : br ? 'break remaining' : garden.phase === 'pausedFocus' ? 'ready when you are' : 'focus remaining'}</span></div></div><h3>${done ? 'Your ' + esc(garden.plant.species) + ' has bloomed.' : br ? 'Let your little plant rest.' : 'Read question one'}</h3><div class="growth-track" aria-label="${Math.floor(m)} of 100 focus minutes">${[0, 1, 2, 3].map(i => `<span><i style="width:${Math.max(0, Math.min(100, (m - i * 25) / 25 * 100))}%"></i></span>`).join('')}</div><p class="bloom-caption"><span data-bloom-progress>${Math.floor(m)} / 100 focus minutes</span> · ${stage}</p><div class="bloom-controls">${bloomControls()}</div>${compact ? '' : `<p class="small muted">Four 25-minute blocks grow one flower. Five-minute breaks between blocks.</p>`}${storageIssue ? '<p role="alert">Could not save on this device. Keep this window open and try again.</p>' : ''}</section>` }
function gardenView() { let counts = Bloom.species.map(name => [name, garden.collection.filter(p => p.species === name)]); return `${heading('greenbook', 'Your little garden', 'A place for everything you’ve grown.')}<div class="tabs"><button data-action="go:collection">Your charms</button><button data-action="go:discover">Discover</button><button aria-pressed="true">Garden</button></div><div class="garden-growing"><div>${flowerArt(artIndex())}</div><div><span class="eyebrow">${garden.phase === 'bloomed' ? 'Just bloomed' : 'Growing'}</span><h2>${garden.phase === 'bloomed' ? garden.plant.species : 'Your mystery flower'}</h2><p>${Math.floor(garden.plant.focusMs / Bloom.MIN)} / 100 focus minutes · ${Bloom.stage(garden)}</p><button class="primary" data-action="go:focus">${garden.phase === 'bloomed' ? 'Plant another seed' : 'Continue growing'}</button></div></div><h2>Bloomed · ${garden.collection.length}</h2>${garden.collection.length ? '' : '<p class="muted">Your first flower will live here after four focus blocks. Your sprout is safe above.</p>'}<div class="flower-grid">${counts.map(([name, plants], i) => `<article class="flower-tile ${plants.length ? '' : 'undiscovered'}">${flowerArt(5 + i)}<h3>${plants.length ? name : 'Undiscovered'}</h3><p>${plants.length ? `${plants.length} grown` : 'A little mystery'}</p>${plants.length ? `<p class="small muted">Latest bloom ${new Date(plants.at(-1).bloomedAt).toLocaleDateString()}</p>` : ''}</article>`).join('')}</div>`; }
const originalTalk = pages.talk, originalToday = pages.today;
pages.focus = () => `${heading('greenbook', 'One little seed. One small step.', 'Your focus grows something lovely.')}<div class="bloom-layout">${bloomCard()}<aside class="bloom-guide"><h2>Room to grow</h2><ol><li>25 minutes · new leaves</li><li>25 minutes · a taller stem</li><li>25 minutes · a little bud</li><li>25 minutes · your flower</li></ol><p class="small muted">Rest for 5 minutes between blocks. Start each next block when you’re ready.</p><div class="seed-note">${flowerArt(1)}<p>Only have 10 minutes?<br><strong>A sprout still counts.</strong><br><span class="small">Come back and finish the same plant.</span></p></div><button data-action="smaller">I’m stuck</button><button data-bloom="save">Save & wrap up</button></aside></div>`;
pages.garden = gardenView;
pages.talk = () => originalTalk().replace('<div class="chat-panel">', `<div class="chat-panel"><div class="talk-focus-strip"><span>Growing · ${Bloom.stage(garden)} · <b data-bloom-clock>${timerText()}</b></span><button data-action="go:focus">Open timer</button></div>`);
pages.today = () => originalToday().replace('<h2>Today’s plan</h2>', `<h2>Today’s plan</h2>`) + `<div class="growth-home"><span>${flowerArt(artIndex(), 'tiny-flower')}</span><div><strong>Your garden is growing</strong><p>${Math.floor(garden.plant.focusMs / Bloom.MIN)} / 100 focus minutes · ${Bloom.stage(garden)}</p></div><button data-action="go:focus">Open timer</button></div>`;
quickChat = function () { return `<section class="popover compact-chat bloom-popup" id="quick"><header><strong>ADHD Fairy</strong><button data-action="go:today" class="ghost" aria-label="Open cottage">⌂</button><button data-action="closequick" class="ghost" aria-label="Close chat">×</button></header><div class="inside">${bloomCard(true)}<div class="quick-transcript">${chatMessages()}</div>${composer('chat', 'Message Fairy…')}</div></section>`; };
pages.popup = () => `<div class="popup-stage">${quickChat()}</div>`;
for (const [value, label] of [['garden', 'Garden'], ['popup', 'Quick chat · flower timer'], ['discover', 'Discover charms'], ['questcreate', 'Quest cover picker']]) { let o = document.createElement('option'); o.value = value; o.textContent = label; $('#preview').append(o) }
const originalRender = render; render = function () { originalRender(); document.querySelectorAll('[data-action="quickstart"]').forEach(b => { b.removeAttribute('data-action'); b.dataset.bloom = 'short'; }); };
// Capture timer commands before the older demonstration handler. No second countdown.

document.addEventListener('click', e => { const b = e.target.closest('[data-bloom]'); if (!b) return; e.preventDefault(); e.stopImmediatePropagation(); bloomNow = Math.max(bloomNow, Date.now()); let a = b.dataset.bloom; if (a === 'start') { garden = Bloom.start(garden, bloomNow); S.session = true; reward('focus'); } if (a === 'short') { garden = Bloom.start(garden, bloomNow, 10); S.session = true; reward('focus'); } if (a === 'pause') garden = Bloom.pause(garden, bloomNow); if (a === 'resume') { garden = Bloom.resume(garden, bloomNow); S.session = true; reward('focus'); } if (a === 'save') { garden = Bloom.pause(garden, bloomNow); persistBloom(); go('wrap'); return; } if (a === 'next') garden = Bloom.next(garden, crypto.randomUUID(), Math.random(), bloomNow); if (a === 'garden') { go('garden'); return; } persistBloom(); render(); celebrate(); }, true);
let lastReal = Date.now(); setInterval(() => { let real = Date.now(); bloomNow += Math.max(0, real - lastReal); lastReal = Math.max(real, lastReal); const before = JSON.stringify([garden.phase, Bloom.stage(garden)]); garden = Bloom.tick(garden, bloomNow); persistBloom(); celebrate(); if (before !== JSON.stringify([garden.phase, Bloom.stage(garden)])) { render(); return; } document.querySelectorAll('[data-bloom-clock]').forEach(el => el.textContent = garden.phase === 'bloomed' ? 'Bloomed!' : timerText()); document.querySelectorAll('[data-bloom-progress]').forEach(el => el.textContent = `${Math.floor(garden.plant.focusMs / Bloom.MIN)} / 100 focus minutes`); document.querySelectorAll('.growth-track').forEach(track => track.querySelectorAll('i').forEach((el, i) => el.style.width = `${Math.max(0, Math.min(100, (garden.plant.focusMs / Bloom.MIN - i * 25) / 25 * 100))}%`)); }, 1000);
// Isolated fixtures are visual QA only. They never write to saved garden state.
window.setBloomPreview = function (name) { previewFixture = true; garden = Bloom.create('preview-flower', .21, bloomNow); let mins = { seed: 0, sprout: 10, leaves: 25, break: 25, tall: 50, bud: 75, bloom: 100 }[name] ?? 0; garden.plant.focusMs = mins * Bloom.MIN; garden.remainingMs = (25 - mins % 25) * Bloom.MIN; garden.phase = name === 'break' ? 'break' : name === 'bloom' ? 'bloomed' : 'pausedFocus'; if (name === 'break') garden.remainingMs = Bloom.BREAK; if (name === 'bloom') { garden.remainingMs = 0; garden.collection = [{ ...garden.plant, bloomedAt: bloomNow }]; } render(); };
let qa = document.createElement('details'); qa.className = 'bloom-preview-controls'; qa.innerHTML = '<summary>Timer mockup states · preview only</summary><p>These samples never change your saved garden.</p>' + ['seed', 'sprout', 'break', 'leaves', 'tall', 'bud', 'bloom'].map(s => `<button data-fixture="${s}">${s}</button>`).join('') + '<button data-fixture="live">Return to saved timer</button>'; $('.demo').after(qa); qa.addEventListener('click', e => { let v = e.target.dataset.fixture; if (!v) return; if (v === 'live') { previewFixture = false; garden = loadBloom(); render() } else window.setBloomPreview(v) });
persistBloom(); render();
// All compact status surfaces use the same remaining-time source.
clock = function () { return timerText() };
const v3Widget = pages.widget;
pages.widget = function () { return v3Widget().replace('<img src="../assets/fairy-full.png" alt="Fairy">', flowerArt(artIndex(), 'widget-flower')).replace('<p class="small muted">Statistics assignment</p>', `<p class="small muted">${Bloom.stage(garden)} · <b data-bloom-clock>${timerText()}</b></p>`) };
render();
celebrate();
